var e={remoteControl:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Envía comandos a la pantalla FilaMind de la impresora.`}},status:{ready:{t:0,b:{t:2,i:[{t:3}],s:`Bus de comandos conectado`}},down:{t:0,b:{t:2,i:[{t:3}],s:`Conectando con el bus de comandos…`}}},show:{title:{t:0,b:{t:2,i:[{t:3}],s:`Mostrar en la pantalla`}},status:{t:0,b:{t:2,i:[{t:3}],s:`Estado`}},control:{t:0,b:{t:2,i:[{t:3}],s:`Control`}},settings:{t:0,b:{t:2,i:[{t:3}],s:`Ajustes`}}},locate:{title:{t:0,b:{t:2,i:[{t:3}],s:`Localizar la pantalla`}},hint:{t:0,b:{t:2,i:[{t:3}],s:`Haz parpadear la pantalla para identificar a qué impresora pertenece.`}},button:{t:0,b:{t:2,i:[{t:3}],s:`Localizar pantalla`}}},message:{title:{t:0,b:{t:2,i:[{t:3}],s:`Enviar un mensaje`}},placeholder:{t:0,b:{t:2,i:[{t:3}],s:`Escribe un mensaje breve para mostrar en la pantalla…`}},level:{t:0,b:{t:2,i:[{t:3}],s:`Nivel`}},info:{t:0,b:{t:2,i:[{t:3}],s:`Información`}},warn:{t:0,b:{t:2,i:[{t:3}],s:`Advertencia`}},send:{t:0,b:{t:2,i:[{t:3}],s:`Enviar`}}},sent:{t:0,b:{t:2,i:[{t:3}],s:`Enviado`}},help:{button:{t:0,b:{t:2,i:[{t:3}],s:`Ayuda`}},title:{t:0,b:{t:2,i:[{t:3}],s:`Control remoto: guía`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Cerrar`}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:`Qué hace esto`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Este panel controla la pantalla táctil FilaMind de la impresora desde aquí: cambia su pestaña, le muestra un mensaje breve o la hace parpadear para que sepas de qué impresora se trata. Son acciones que solo afectan a la pantalla: nunca mueven la impresora ni cambian ningún ajuste.`}}},commands:{title:{t:0,b:{t:2,i:[{t:3}],s:`Los comandos`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Mostrar cambia la pantalla a su pestaña Estado, Control o Ajustes. Localizar hace parpadear la pantalla durante unos segundos. Mensaje muestra una nota breve (información o advertencia). Los comandos llegan a cualquier pantalla FilaMind de esta impresora; no se envía nada mientras el bus de comandos sigue conectándose.`}}}}},requiresScreen:{t:0,b:{t:2,i:[{t:3}],s:`Estos controles manejan la pantalla FilaMind de la impresora. Instala FilaMind 3D en esta impresora para usarlos.`}}}};export{e as default};